<script setup>
import {Head,Link,router} from '@inertiajs/vue3'
import {reactive} from 'vue'
import AppLayout from '../../../Layouts/AppLayout.vue'
const p=defineProps({users:Object,filters:Object})
const form=reactive({search:p.filters.search||'',role:p.filters.role||'',active:p.filters.active??'',sort:p.filters.sort||'newest'})
const apply=()=>router.get('/admin/users',form,{preserveState:true,replace:true})
const labels={ADMIN:'مدیر',TEACHER:'مدرس',STUDENT:'هنرجو'}
</script>
<template><AppLayout><Head title="مدیریت کاربران"/><div class="space-y-5"><section class="rounded-2xl border bg-white p-5"><div class="flex flex-wrap items-center justify-between gap-3"><h1 class="text-xl font-bold">کاربران</h1><Link href="/admin/users/create" class="rounded-xl bg-teal-700 px-4 py-2 text-sm font-bold text-white">کاربر جدید</Link></div><form class="mt-5 grid gap-3 sm:grid-cols-2 lg:grid-cols-5" @submit.prevent="apply"><input v-model="form.search" placeholder="نام، موبایل یا ایمیل"><select v-model="form.role"><option value="">همه نقش‌ها</option><option value="ADMIN">مدیر</option><option value="TEACHER">مدرس</option><option value="STUDENT">هنرجو</option></select><select v-model="form.active"><option value="">همه وضعیت‌ها</option><option value="1">فعال</option><option value="0">غیرفعال</option></select><select v-model="form.sort"><option value="newest">جدیدترین</option><option value="oldest">قدیمی‌ترین</option><option value="name">نام</option></select><button class="rounded-xl border px-4 py-2">اعمال فیلتر</button></form></section><section class="grid gap-3 sm:grid-cols-2"><article v-for="user in users.data" :key="user.id" class="rounded-2xl border bg-white p-4"><div class="flex items-center gap-3"><img v-if="user.avatar_url" :src="user.avatar_url" alt="" class="h-12 w-12 rounded-full object-cover"><div v-else class="grid h-12 w-12 place-items-center rounded-full bg-teal-50 font-bold text-teal-800">{{user.first_name?.[0]}}{{user.last_name?.[0]}}</div><div><Link :href="`/admin/users/${user.id}`" class="font-bold text-teal-800">{{user.name}}</Link><p class="text-sm text-slate-500">{{labels[user.role]}} · {{user.is_active?'فعال':'غیرفعال'}}</p></div></div><div class="mt-3 text-sm"><p dir="ltr" class="text-right">{{user.mobile}}</p><p>{{user.email||'بدون ایمیل'}}</p></div><div class="mt-3 flex gap-4 text-sm"><Link :href="`/admin/users/${user.id}`" class="text-teal-700">جزئیات</Link><Link :href="`/admin/users/${user.id}/edit`" class="text-teal-700">ویرایش</Link></div></article></section><div class="flex flex-wrap gap-2"><Link v-for="link in users.links" :key="link.label" :href="link.url||''" v-html="link.label" class="rounded-lg border px-3 py-1 text-sm" :class="{'bg-teal-700 text-white':link.active,'pointer-events-none opacity-40':!link.url}"/></div></div></AppLayout></template>
